const listUnavailableRoomIDsForStay = `-- name: ListUnavailableRoomIDsForStay :many
SELECT DISTINCT room_id
FROM (
    SELECT b.room_id
    FROM bookings b
    WHERE b.room_id = ANY($1::uuid[])
      AND b.status IN ('pending', 'confirmed', 'checked_in')
      AND b.stay && daterange($2::date, $3::date, '[)')
    UNION
    SELECT h.room_id
    FROM reservation_holds h
    WHERE h.room_id = ANY($1::uuid[])
      AND h.status = 'active'
      AND h.expires_at > $4
      AND h.stay && daterange($2::date, $3::date, '[)')
) unavailable
`

type ListUnavailableRoomIDsForStayParams struct {
	Column1   []uuid.UUID `json:"column_1"`
	Column2   pgtype.Date `json:"column_2"`
	Column3   pgtype.Date `json:"column_3"`
	ExpiresAt time.Time   `json:"expires_at"`
}

func (q *Queries) ListUnavailableRoomIDsForStay(ctx context.Context, arg ListUnavailableRoomIDsForStayParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, listUnavailableRoomIDsForStay,
		arg.Column1,
		arg.Column2,
		arg.Column3,
		arg.ExpiresAt,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var room_id uuid.UUID
		if err := rows.Scan(&room_id); err != nil {
			return nil, err
		}
		items = append(items, room_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

